//! Intensity stereo coding (ISC)

use super::{channel_info::IcsInfo, constants::*, utils::*};
use crate::common::pow::scale_factor_2_exp;
use itertools::{izip, Itertools};

/// Applies intensity stereo coding tool
///
/// # Parameters
///
/// - `ics_info`: Individual channel stream info data
/// - `code_book`: Codebook for each window and scale factor band
/// - `scale_factor`: Spectral scale factors for each scale factor band in each window
/// - `ms_used`: Flags indicating usage of MS (IS and MS are mutually exclusive)
/// - `spectrum_l`: Spectral values of the left channel
/// - `spectrum_r`: Spectral values of the right channel
///
/// # Return
/// `()`
///
/// # Examples
/// ```
/// use aac::aac_dec::intensity::*;
/// use aac::aac_dec::{channel_info::IcsInfo, constants, utils};
///
/// let ics_info: IcsInfo = Default::default();
/// let code_book = [utils::CBTYPE_INTENSITY_HCB; constants::MAX_WINS_X_SFBS];
/// let scale_factors = [1_i16; constants::MAX_WINS_X_SFBS];
/// let ms_used = [0_u8; constants::MAX_WINS_X_SFBS];
/// let mut spectrum = [0_f32; 2 * constants::MAX_FRAMESIZE];
///
/// apply_is(
///     &ics_info,
///     &code_book,
///     &scale_factors,
///     &ms_used,
///     &mut spectrum,
/// );
/// ```
pub fn apply_is(
    ics_info: &IcsInfo,
    code_book: &[u8],
    scale_factors: &[i16],
    ms_used: &[u8],
    spectrum: &mut [f32],
) {
    let scale_factor_bands_offsets = ics_info.scale_factor_bands();
    let window_group_lengths = ics_info.window_group_lengths();
    let scale_factor_bands_transmitted = ics_info.max_sf_bands();
    let window_length = spectrum.len() / ics_info.windows_per_frame() / 2;
    let (spectrum_left, spectrum_right) = spectrum.split_at_mut(spectrum.len() / 2);

    let mut window: usize = 0;

    for ((window_group_idx, inner_scale_factors), inner_code_book, window_group_length) in izip!(
        scale_factors
            .chunks_exact(MAX_WINS_X_SFBS / ics_info.windows_per_frame())
            .enumerate(),
        code_book.chunks_exact(MAX_WINS_X_SFBS / ics_info.windows_per_frame()),
        window_group_lengths.iter(),
    )
    .take(ics_info.n_window_groups())
    {
        let group_mask = 1_u8 << window_group_idx;

        for (inner_left_spectrum, inner_right_spectrum) in izip!(
            spectrum_left[window * window_length..].chunks_exact(window_length),
            spectrum_right[window * window_length..].chunks_exact_mut(window_length)
        )
        .take(usize::from(*window_group_length))
        {
            window += 1;
            for (isf, icb, ms_item, (sfb_offset_curr, sfb_offset_next)) in izip!(
                inner_scale_factors.iter(),
                inner_code_book.iter(),
                ms_used.iter(),
                scale_factor_bands_offsets.iter().tuple_windows()
            )
            .take(scale_factor_bands_transmitted)
            {
                if *icb == CBTYPE_INTENSITY_HCB || *icb == CBTYPE_INTENSITY_HCB2 {
                    let band_scale = -(*isf);
                    let mut scale = scale_factor_2_exp(band_scale);
                    if ms_item & group_mask != 0 {
                        if *icb == CBTYPE_INTENSITY_HCB
                        // _NOT_ in-phase
                        {
                            scale = -scale;
                        }
                    } else if *icb == CBTYPE_INTENSITY_HCB2
                    // out-of-phase
                    {
                        scale = -scale;
                    }
                    inner_right_spectrum[usize::from(*sfb_offset_curr)..]
                        .iter_mut()
                        .zip(inner_left_spectrum[usize::from(*sfb_offset_curr)..].iter())
                        .take(usize::from(*sfb_offset_next - *sfb_offset_curr))
                        .for_each(|(r, l)| *r = *l * scale);
                }
            }
        }
    }
}

